class Solution {
    public int differenceOfSum(int[] nums){
        int elementSum=0,digitSum=0;
        for(int value:nums){
            elementSum+=value;
            for(int copy=value;copy>0;copy/=10)digitSum+=copy%10;
        }
        return Math.abs(elementSum-digitSum);
    }
}

code.kotlin:
class Solution {
    fun differenceOfSum(nums:IntArray):Int{
        var elementSum=0;
        var digitSum=0;
        for(value in nums){
            elementSum+=value;
            var copy=value;
            while(copy>0){
                digitSum+=copy%10;
                copy/=10
            }
        };
        return kotlin.math.abs(elementSum-digitSum)
    }
}

